CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE currencies(code varchar(3) PRIMARY KEY, name varchar(40) NOT NULL, scale smallint NOT NULL CHECK(scale BETWEEN 0 AND 6));
INSERT INTO currencies(code,name,scale) VALUES ('USD','US Dollar',2),('KHR','Cambodian Riel',0);
CREATE TABLE branches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(30) NOT NULL UNIQUE, name varchar(120) NOT NULL, address text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(40) NOT NULL UNIQUE, name varchar(120) NOT NULL, type varchar(24) NOT NULL CHECK(type IN ('CENTRAL_WAREHOUSE','BRANCH','IN_TRANSIT')), branch_id uuid REFERENCES branches(id), active boolean NOT NULL DEFAULT true, CHECK((type='BRANCH')=(branch_id IS NOT NULL)));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username varchar(120) NOT NULL UNIQUE, password_hash varchar(100) NOT NULL, display_name varchar(160) NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(40) NOT NULL UNIQUE, name varchar(80) NOT NULL);
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(80) NOT NULL UNIQUE, description text NOT NULL);
CREATE TABLE user_roles(user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), PRIMARY KEY(user_id,role_id));
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id), permission_id uuid NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_branches(user_id uuid NOT NULL REFERENCES users(id), branch_id uuid NOT NULL REFERENCES branches(id), PRIMARY KEY(user_id,branch_id));
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL UNIQUE, parent_id uuid REFERENCES categories(id), active boolean NOT NULL DEFAULT true);
CREATE TABLE brands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(120) NOT NULL UNIQUE, active boolean NOT NULL DEFAULT true);
CREATE TABLE units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(20) NOT NULL UNIQUE, name varchar(80) NOT NULL UNIQUE);
CREATE TABLE products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sku varchar(64) NOT NULL UNIQUE, barcode varchar(80) UNIQUE, name varchar(180) NOT NULL, description text, category_id uuid REFERENCES categories(id), brand_id uuid REFERENCES brands(id), unit_id uuid NOT NULL REFERENCES units(id), reorder_level integer NOT NULL DEFAULT 0 CHECK(reorder_level>=0), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_prices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), currency_code varchar(3) NOT NULL REFERENCES currencies(code), amount numeric(19,4) NOT NULL CHECK(amount>=0), effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, UNIQUE(product_id,currency_code,effective_from));
CREATE TABLE exchange_rates(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), base_currency varchar(3) NOT NULL REFERENCES currencies(code), quote_currency varchar(3) NOT NULL REFERENCES currencies(code), rate numeric(24,10) NOT NULL CHECK(rate>0), effective_at timestamptz NOT NULL, source varchar(120), entered_by uuid REFERENCES users(id), CHECK(base_currency<>quote_currency));
CREATE TABLE stock_balances(location_id uuid NOT NULL REFERENCES locations(id), product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0), version bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(location_id,product_id));
CREATE TABLE stock_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_no varchar(40) NOT NULL UNIQUE, source_location_id uuid NOT NULL REFERENCES locations(id), destination_location_id uuid NOT NULL REFERENCES locations(id), status varchar(20) NOT NULL CHECK(status IN ('PENDING','APPROVED','IN_TRANSIT','RECEIVED','CANCELLED')), idempotency_key varchar(100) NOT NULL UNIQUE, created_by uuid NOT NULL REFERENCES users(id), approved_by uuid REFERENCES users(id), dispatched_by uuid REFERENCES users(id), received_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), dispatched_at timestamptz, received_at timestamptz, CHECK(source_location_id<>destination_location_id));
CREATE TABLE stock_transfer_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), transfer_id uuid NOT NULL REFERENCES stock_transfers(id), product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>0), UNIQUE(transfer_id,product_id));
CREATE TABLE stock_movements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), location_id uuid NOT NULL REFERENCES locations(id), product_id uuid NOT NULL REFERENCES products(id), quantity_delta integer NOT NULL CHECK(quantity_delta<>0), movement_type varchar(32) NOT NULL, source_type varchar(32) NOT NULL, source_id uuid NOT NULL, source_line_id uuid, actor_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_type,source_id,source_line_id,location_id,movement_type));
CREATE INDEX stock_movements_product_time_idx ON stock_movements(product_id,location_id,created_at DESC);
CREATE TABLE customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(40) UNIQUE, name varchar(160) NOT NULL, phone varchar(40), email varchar(180), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(40) UNIQUE, name varchar(160) NOT NULL, phone varchar(40), email varchar(180), address text, active boolean NOT NULL DEFAULT true);
CREATE TABLE sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), branch_id uuid NOT NULL REFERENCES branches(id), invoice_no varchar(48) NOT NULL, cashier_id uuid NOT NULL REFERENCES users(id), customer_id uuid REFERENCES customers(id), status varchar(20) NOT NULL CHECK(status IN ('COMPLETED','VOIDED','PARTIALLY_REFUNDED','REFUNDED')), currency_code varchar(3) NOT NULL REFERENCES currencies(code), subtotal numeric(19,4) NOT NULL, discount_total numeric(19,4) NOT NULL, total numeric(19,4) NOT NULL, idempotency_key varchar(100) NOT NULL UNIQUE, completed_at timestamptz NOT NULL DEFAULT now(), UNIQUE(branch_id,invoice_no));
CREATE INDEX sales_branch_date_idx ON sales(branch_id,completed_at DESC);
CREATE TABLE sale_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id), product_id uuid NOT NULL REFERENCES products(id), sku_snapshot varchar(64) NOT NULL, name_snapshot varchar(180) NOT NULL, unit_snapshot varchar(80) NOT NULL, quantity integer NOT NULL CHECK(quantity>0), unit_price numeric(19,4) NOT NULL, discount numeric(19,4) NOT NULL DEFAULT 0, line_total numeric(19,4) NOT NULL);
CREATE TABLE sale_payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES sales(id), currency_code varchar(3) NOT NULL REFERENCES currencies(code), amount numeric(19,4) NOT NULL CHECK(amount>0), method varchar(24) NOT NULL);
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), refund_no varchar(48) NOT NULL UNIQUE, sale_id uuid NOT NULL REFERENCES sales(id), status varchar(20) NOT NULL CHECK(status IN ('APPROVED','REJECTED')), reason text NOT NULL, created_by uuid NOT NULL REFERENCES users(id), approved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refund_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), refund_id uuid NOT NULL REFERENCES refunds(id), sale_line_id uuid NOT NULL REFERENCES sale_lines(id), quantity integer NOT NULL CHECK(quantity>0), amount numeric(19,4) NOT NULL CHECK(amount>=0), restock boolean NOT NULL DEFAULT false);
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_no varchar(48) NOT NULL UNIQUE, supplier_id uuid NOT NULL REFERENCES suppliers(id), warehouse_location_id uuid NOT NULL REFERENCES locations(id), status varchar(20) NOT NULL CHECK(status IN ('DRAFT','ORDERED','PARTIALLY_RECEIVED','RECEIVED','CANCELLED')), currency_code varchar(3) NOT NULL REFERENCES currencies(code), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE purchase_order_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id), product_id uuid NOT NULL REFERENCES products(id), name_snapshot varchar(180) NOT NULL, ordered_quantity integer NOT NULL CHECK(ordered_quantity>0), received_quantity integer NOT NULL DEFAULT 0 CHECK(received_quantity>=0 AND received_quantity<=ordered_quantity), unit_cost numeric(19,4) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE goods_receipts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_no varchar(48) NOT NULL UNIQUE, purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id), status varchar(20) NOT NULL CHECK(status IN ('CONFIRMED','CANCELLED')), idempotency_key varchar(100) NOT NULL UNIQUE, received_by uuid NOT NULL REFERENCES users(id), received_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE goods_receipt_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), receipt_id uuid NOT NULL REFERENCES goods_receipts(id), purchase_order_line_id uuid NOT NULL REFERENCES purchase_order_lines(id), product_id uuid NOT NULL REFERENCES products(id), quantity integer NOT NULL CHECK(quantity>0), unit_cost numeric(19,4) NOT NULL CHECK(unit_cost>=0));
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action varchar(80) NOT NULL, entity_type varchar(80) NOT NULL, entity_id uuid, branch_id uuid REFERENCES branches(id), request_id varchar(100), details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO roles(code,name) VALUES ('SUPER_ADMIN','Super Admin'),('BRANCH_MANAGER','Branch Manager'),('CASHIER','Cashier'),('INVENTORY_STAFF','Inventory Staff'),('VIEWER','Viewer');
INSERT INTO units(code,name) VALUES ('EA','Each');
CREATE UNIQUE INDEX locations_one_branch_location ON locations(branch_id) WHERE type='BRANCH';
INSERT INTO permissions(code,description) VALUES
('branches.read','Read branches'),('branches.manage','Manage branches'),('users.manage','Manage users and assignments'),('roles.manage','Manage roles and permissions'),('catalog.read','Read product catalog'),('catalog.manage','Manage product catalog and prices'),('inventory.read','Read stock and movements'),('inventory.adjust','Adjust stock'),('inventory.transfer','Create and process stock transfers'),('sales.read','Read sales'),('sales.create','Create sales'),('sales.refund','Request or approve refunds'),('purchases.read','Read purchases'),('purchases.manage','Create purchase orders'),('purchases.receive','Receive purchased goods'),('reports.read','Read reports'),('audit.read','Read audit log') ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN ('branches.read','catalog.read','catalog.manage','inventory.read','inventory.adjust','inventory.transfer','sales.read','sales.create','sales.refund','purchases.read','reports.read') WHERE r.code='BRANCH_MANAGER' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN ('catalog.read','sales.read','sales.create') WHERE r.code='CASHIER' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN ('catalog.read','inventory.read','inventory.adjust','inventory.transfer','purchases.read','purchases.manage','purchases.receive') WHERE r.code='INVENTORY_STAFF' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.code IN ('branches.read','catalog.read','inventory.read','sales.read','purchases.read','reports.read') WHERE r.code='VIEWER' ON CONFLICT DO NOTHING;
